#include <vector>
#include <algorithm>

class Solution {
public:
    int maxTeamSize(std::vector<std::vector<int>>& intervals) {
        std::vector<std::pair<int, int>> events;
        for (const auto& iv : intervals) {
            events.push_back({iv[0], 1});
            events.push_back({iv[1] + 1, -1});
        }
        std::sort(events.begin(), events.end());
        int cur = 0, maxTeam = 0;
        for (const auto& [t, delta] : events) {
            cur += delta;
            maxTeam = std::max(maxTeam, cur);
        }
        return maxTeam;
    }
};

import java.util.*;

class Solution {
    public int maxTeamSize(int[][] intervals) {
        List<int[]> events = new ArrayList<>();
        for (int[] iv : intervals) {
            events.add(new int[]{iv[0], 1});
            events.add(new int[]{iv[1] + 1, -1});
        }
        events.sort((a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : Integer.compare(a[1], b[1]));
        int cur = 0, maxTeam = 0;
        for (int[] ev : events) {
            cur += ev[1];
            maxTeam = Math.max(maxTeam, cur);
        }
        return maxTeam;
    }
}

function maxTeamSize(intervals) {
    const events = [];
    for (const [s, e] of intervals) {
        events.push([s, 1]);
        events.push([e + 1, -1]);
    }
    events.sort((a, b) => a[0] !== b[0] ? a[0] - b[0] : a[1] - b[1]);
    let cur = 0, maxTeam = 0;
    for (const [t, delta] of events) {
        cur += delta;
        if (cur > maxTeam) maxTeam = cur;
    }
    return maxTeam;
}
